<template>
   <div class="discount-goods" v-show="goodsList.length">
     <div class="title"><i class="icon iconfont main-color-bg">&#xe617;</i><span>超值热卖</span></div>
     <ul class="list">
       <li class="item" v-for="item in goodsList" :key="item.goods_id" @click="checkGoodsDetail(item.goods_id)">
         <div class="goods-img">
           <img class="img" :src="item.image" alt="">
           <div class="icon"><span class="txt">省{{item.minus}}元</span></div>
           <img class="top-icon" v-if="item.labels && item.labels.type == 1" :src="item.labels.image" alt="">
           <span class="top-icon txt-icon main-color-bg" :style="{background:'-webkit-linear-gradient(top,'+ item.labels.color +','+ item.labels.color2 +') !important'}" v-if="item.labels && item.labels.type == 0">{{item.labels.name}}</span>
         </div>
         <div class="goods-title">{{ item.limit_buy == 0 ? '' : '【限购'+item.limit_buy+'份】' }}{{item.name}}</div>
         <div class="price-box">
           <div>
             <div>
               <span class="now now-icon main-color-font">¥</span>
               <span class="now main-color-font">{{item.price}}</span>
               <span class="old">¥{{item.old_price}}</span>
             </div>
             <div class="num">已拼{{item.sell_count}}件</div>
           </div>
           <AddToCart v-if="item.stock_status == 0 && item.is_no_start == 0 && item.limit_buy_status == 0" type="middle" :goodsId="item.goods_id" :from="from"/>
         </div>
         <div class="close-buy" v-if="item.stock_status == 1 || item.is_no_start == 1 || item.limit_buy_status == 1">
           <div class="icon-box">
             <div class="icon" v-if=" item.stock_status == 1 ">已抢光</div>
             <div class="icon" v-else-if=" item.is_no_start == 1 || item.limit_buy_status == 1">未开始</div>
           </div>
         </div>
       </li>
     </ul>
   </div>
</template>

<script>
import AddToCart from '../AddToCart/AddToCart'
import PubSub from 'pubsub-js'
export default {
  name: 'DiscountGoods',
  data () {
    return {
      goodsList: [],
      isAlive: false,
      leader_id: ''
    }
  },
  props: [ 'from' ],
  created () {
    this.leader_id = this.$util.storage.get('leader_id')
    this.getGoods()
    // // 订阅购物车数量变化
    PubSub.subscribe('cartInfo', (event, data) => {
      console.log('超值抢购', data, this.leader_id+'k', this.$util.storage.get('leader_id')+'k')
      if (data.allNeedRefresh && this.leader_id != this.$util.storage.get('leader_id')) {
        this.leader_id = this.$util.storage.get('leader_id')
        this.getGoods()
      }
    })
  },
  methods: {
    async getGoods () {
      let res = await this.$api.getHotGoods({ leader_id: this.leader_id })
      if (!res) return
      this.goodsList = res
    },
    checkGoodsDetail (id) {
      this.$router.push({ path: '/goods', query: { goodsId: id, leaderId: this.leader_id } })
    }
  },
  components: {
    AddToCart
  }

}
</script>

<style lang="stylus" scoped>
.discount-goods
  .title
    font-size 16px
    font-weight bold
    margin 15px 0
    text-align center
    flexbox()
    align-items center
    justify-content center
    .icon
      font-size 12px
      display inline-block
      width 18px
      height 18px
      text-align center
      line-height 18px
      border-radius 50%
      background $color-main
      color #fff
      margin-right 10px
  .list
    flexbox()
    flex-wrap wrap
    padding 0 15px
    .item
      background #fff
      padding 12px
      margin-bottom 10px
      width calc(50% - 5px)
      border-radius 5px
      box-sizing border-box
      position relative
      &:nth-child(odd)
        margin-right 5px
      &:nth-child(even)
        margin-left 5px
      .goods-img
        width 100%
        padding-top 100%
        font-size 0
        position relative
        .img
          position absolute
          top 0
          left 0
          width 100%
          height 100%
          object-fit cover
        .icon
          position absolute
          left 0
          bottom 0
          right 0
          height 20px
          text-align center
          .txt
            display inline-block
            height 0
            border-width 0 5px 20px 5px
            border-style none solid solid
            border-color transparent transparent $color-main
            font-size 12px
            line-height 20px
            color #fff
            padding 0 10px
        .top-icon
          position absolute
          top 0
          left 0
          width 30px
          &.txt-icon
            height 30px
            color #fff
            line-height 30px
            font-size 12px
            text-align center
            overflow hidden
            background  #06c1ae;
      .goods-title
        font-size 12px
        margin-top 5px
        line-height 1.5
        height 36px
        ellipsis(2)
      .price-box
        margin-top 10px
        flexbox()
        justify-content space-between
        align-items center
        line-height 1.3
        .now
          font-size 16px
          font-weight bold
          color $color-main
          margin-right 5px
        .now-icon
          margin-right 0
          font-size 12px
        .old
          color #999999
          text-decoration line-through
        .num
          font-size 12px
          color #999999
        .start-tip
          color #bbb
          border 1PX solid #e5e5e5
          border-radius 2px
          padding 2px 5px
      .close-buy
        position absolute
        top 0
        left 0
        right 0
        bottom 0
        background rgba(255, 255, 255, .4)
        padding 40px
        .icon-box
          width 100%
          padding-top 100%
          position relative
          .icon
            position absolute
            top 0
            left 0
            right 0
            bottom 0
            background rgba(0, 0, 0, .5)
            color #fff
            border-radius 50%
            flexbox()
            justify-content center
            align-items center
            font-size 16px
</style>
