import Vue from 'vue'
import Router from 'vue-router'
import Index from './pages/Index/Index.vue'

Vue.use(Router)

const router = new Router({
  base: process.env.VUE_APP_BASE_API,
  // mode: 'history',
  linkActiveClass: 'active',
  routes: [
    {
      path: '/',
      redirect: '/index'
    },
    {
      path: '/index',
      name: 'index',
      component: Index,
      meta: {
        showFooter: true,
        keepAlive: true
      }
    },
    {
      path: '/classify',
      name: 'Classify',
      component: () => import('./pages/Classify/Classify.vue'),
      meta: {
        showFooter: true,
        keepAlive: true
      }
    },
    {
      path: '/cart',
      name: 'Cart',
      component: () => import('./pages/Cart/Cart.vue'),
      meta: {
        showFooter: true
      }
    },
    {
      path: '/my',
      name: 'My',
      component: () => import('./pages/My/My.vue'),
      meta: {
        showFooter: true,
        keepAlive: true
      }
    },
    {
      path: '/search',
      name: 'Search',
      component: () => import('./pages/Search/Search.vue')
    },
    {
      path: '/leader',
      name: 'Leader',
      component: () => import('./pages/Leader/Leader.vue')
    },
    {
      path: '/leaderList',
      name: 'LeaderList',
      component: () => import('./pages/LeaderList/LeaderList.vue')
    },
    {
      path: '/address',
      name: 'Address',
      component: () => import('./pages/Address/Address.vue')
    },
    {
      path: '/cityList',
      name: 'CityList',
      component: () => import('./pages/CityList/CityList.vue')
    },
    {
      path: '/goods',
      name: 'Goods',
      component: () => import('./pages/Goods/Goods.vue')
    },
    {
      path: '/qrCode',
      name: 'QrCode',
      component: () => import('./pages/QrCode/QrCode.vue')
    },
    {
      path: '/dayBuy',
      name: 'DayBuy',
      component: () => import('./pages/DayBuy/DayBuy.vue')
    },
    {
      path: '/limitBuy',
      name: 'LimitBuy',
      component: () => import('./pages/LimitBuy/LimitBuy.vue')
    },
    {
      path: '/confirm',
      name: 'Confirm',
      component: () => import('./pages/Confirm/Confirm.vue')
    },
    {
      path: '/coupon',
      name: 'Coupon',
      component: () => import('./pages/Coupon/Coupon.vue')
    },
    {
      path: '/reply',
      name: 'Reply',
      component: () => import('./pages/Reply/Reply.vue')
    },
    {
      path: '/newUser',
      name: 'NewUser',
      component: () => import('./pages/NewUser/NewUser.vue')
    }
  ]
})

router.beforeEach((to, from, next) => {
  console.log('beforeeach', to, from)
  next()
})

export default router
