<template>
  <div id="footer" ref="footer">
    <router-link class="item" to="/index" active-class="active" replace>
      <div><i class="icon iconfont">&#xe908;</i></div>
      <div>首页</div>
    </router-link>
    <router-link class="item" to="/classify" active-class="active" replace>
      <div><i class="icon iconfont">&#xe621;</i></div>
      <div>分类</div>
    </router-link>
    <div class="item" v-if=" showBbs == 1 "  @click="goUrl('/wap.php?g=Wap&c=Portal&a=index')">
      <div><i class="icon iconfont">&#xe656;</i></div>
      <div>小区说</div>
    </div>
    <router-link class="item" to="/cart" active-class="active" replace>
      <div class="cart">
        <i class="icon iconfont">&#xe628;</i>
        <span class="num" v-show="totalNum && totalNum < 100">{{totalNum}}</span>
        <span class="num" v-show="totalNum > 99">99+</span>
      </div>
      <div>购物车</div>
    </router-link>
    <router-link class="item" to="/my" active-class="active" replace>
      <div><i class="icon iconfont">&#xe619;</i></div>
      <div>我的</div>
    </router-link>
  </div>
</template>

<script>
import PubSub from 'pubsub-js'
export default {
  name: 'Footer',
  data () {
    return {
      totalNum: 0
    }
  },
  props: ['showBbs'],
  created () {
    let obj = this.$global.goodsNumObj
    if (obj && obj.totalNum) {
      this.totalNum = obj.totalNum
    }
    // 订阅购物车数量变化
    PubSub.subscribe('cartInfo', (event, data) => {
      this.totalNum = data.num
    })
  },
  mounted () {
    this.$global.footerHeight = this.$refs.footer.clientHeight
    console.log('底部导航', this.$refs.footer.clientHeight)
  },
  methods: {
    goUrl (url) {
      location.href = process.env.VUE_APP_BASE_API + url + '&ticket=' + this.$util.storage.get('ticket') + '&device_id=packapp'
    }
  }
}
</script>

<style lang="stylus" scoped>
#footer
  width 100%
  height 45px
  background #fff
  border-top 1PX solid #efefef
  flexbox()
  align-items center
  position fixed
  bottom 0
  @media only screen and (device-width: 375px) and (device-height: 812px) and (-webkit-device-pixel-ratio: 3)
    padding-bottom 30px
  @media only screen and (device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio:3)
    padding-bottom 30px
  @media only screen and (device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio:2)
    padding-bottom 30px
  .item
    width 25%
    height 100%
    text-align center
    font-size 12px
    color #999
    position relative
    padding-top 8px
    box-sizing border-box
    &.active
      color $color-main
    .icon
      font-size 20px
    .cart
      position relative
      display inline-block
      .num
        position absolute
        right -14px
        top -5px
        background red
        color #fff
        padding 2px
        min-width 14px
        text-align center
        box-sizing border-box
        border-radius 8px
        font-size 10px
</style>
