<template>
  <div id="app">
    <Footer v-show="$route.meta.showFooter" :showBbs="openBbs"/>
    <keep-alive>
      <router-view class="app-content" v-if="isRouterAlive && $route.meta.keepAlive" :class="{'has-footer': $route.meta.showFooter}" />
    </keep-alive>
    <router-view class="app-content" v-if="isRouterAlive && !$route.meta.keepAlive" :class="{'has-footer': $route.meta.showFooter}" />
  </div>
</template>
<script>
import Footer from './components/Footer/Footer'
export default {
  name: 'App',
  data () {
    return {
      openBbs: 0,
      leader: '',
      selectCurrent: true,
      showAddressMask: true,
      isRouterAlive: true,
      lng: '',
      lat: ''
    }
  },
  created () {
    if (this.$util.checkApp()) {
      if (!this.$util.getTicket() && this.$util.storage.get('ticket')) {
        this.$util.storage.remove('ticket')
        this.$util.storage.remove('device')
      } else if (this.$util.getTicket()) {
        this.$util.storage.set('ticket', this.$util.getTicket())
        this.$util.storage.set('device', this.$util.getDeviceid())
      }
    } else {
      if (this.$util.cookie.get('login_status') && this.$util.cookie.get('login_status') == 'login') {
        this.$util.storage.set('ticket', this.$util.cookie.get('user_ticket'))
        this.$util.cookie.get('user_device_id') && this.$util.storage.set('device', this.$util.cookie.get('user_device_id'))
      } else if (this.$util.cookie.get('login_status') == 'logout') {
        console.log('清除ticket', this.$util.cookie.get('login_status'))
        this.$util.storage.remove('ticket')
        this.$util.storage.remove('device')
      }
    }
    this.getIndexConfig()
    // if (this.$util.storage.get('ticket')) {
    //   if (this.$route.name == 'index' && this.$util.storage.get('leader_id')) {
    //     if (this.$util.checkWeixin() && this.$util.checkAndroid()) {
    //       this.$util.getWxconfig(this.getLocation)
    //     } else {
    //       this.getLocation()
    //     }
    //   }
    // }
  },
  methods: {
    reload () {
      this.isRouterAlive = false
      this.$nextTick(() => (this.isRouterAlive = true))
    },
    confirmSelect () {
      if (!this.selectCurrent) {
        console.log('99999999999', this.$children[1])
        this.$util.storage.set('leader_id', this.leader.last_leader.id)
        this.leader_id = this.$children[1].leader_id = this.leader.last_leader.id
        this.$children[1].getIndexInfo()
      }
      this.showAddressMask = false
    },
    selectAddress (value) {
      this.selectCurrent = value
    },
    goLeaderList () {
      this.showAddressMask = false
      this.$router.push('/leaderList')
    },
    getLocation () {
      // 获取定位信息
      this.$util.getLocation(this.getLocationOk)
    },
    // 定位成功的回调
    getLocationOk (res) {
      if (!res.errorMsg) {
        this.lng = res.lng
        this.lat = res.lat
      }
      this.getAddressDiff()
    },
    async getIndexConfig () {
      // this.$messageBox.alert('22')
      let res = await this.$api.getConfig()
      if (!res) return
      this.$global.config = res
      this.$global.city = {
        area_id: res.city.area_id,
        area_name: res.city.area_name
      }
      if (res.config.open_bbs == 1) {
        this.openBbs = 1
      }
      this.changeMainColor(res.config.mobile_head_color)
    },
    changeMainColor (color) {
      let style = `.main-color-bg, .index-wrapper .page-scroll .page-wrapper .img-swiper .img-bullet-active, .index-wrapper .page-scroll .page-wrapper .nav-swiper .nav-bullet-active, .index-wrapper .page-scroll .page-wrapper .activity-box .activity-goods .time-box .list-wrapper .list .item.active, .limit-buy .time-box .list-wrapper .list .item.active{background-color:${color} !important;}
      .main-color-font, #footer .item.active, .classify .classify-content .nav-box .wrapper .list .item.active .txt{color:${color} !important;}
      .main-color-border, .index-wrapper .header-box .nav-fixed .now-activity, .classify .classify-content .nav-box .wrapper .list .item.active .txt{border-color:${color} !important;}
      .discount-goods .list .item .goods-img .icon .txt{border-color:transparent transparent ${color} !important;}
      #app .address-mask .mask-content .item .info-box .leader .tag .icon{border-right-color: ${color} !important;}`
      var ele = document.createElement('style')
      ele.innerHTML = style
      document.getElementsByTagName('head')[0].appendChild(ele)
    },
    async getAddressDiff () {
      let param = {
        leader_id: this.$util.storage.get('leader_id'),
        lng: this.lng,
        lat: this.lat
      }
      let res = await this.$api.getAddressDiff(param)
      if (!res || res.length == 0) return
      this.leader = res
    }
  },
  components: {
    Footer
  }
}
</script>
<style lang="stylus">
#app
  -webkit-font-smoothing antialiased
  -moz-osx-font-smoothing grayscale
  color #000
  width 100%
  height 100%
  font-size 12px
  position relative
  z-index 5
  .app-content
    overflow hidden
    height 100%
    box-sizing border-box
    @media only screen and (device-width: 375px) and (device-height: 812px) and (-webkit-device-pixel-ratio: 3)
      padding-bottom 30px
    @media only screen and (device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio:3)
      padding-bottom 30px
    @media only screen and (device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio:2)
      padding-bottom 30px
    &.has-footer
      height calc(100% - 46px)
      padding-bottom 0
      @media only screen and (device-width: 375px) and (device-height: 812px) and (-webkit-device-pixel-ratio: 3)
        height calc(100% - 76px)
      @media only screen and (device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio:3)
        height calc(100% - 76px)
      @media only screen and (device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio:2)
        height calc(100% - 76px)
  .address-mask
    position absolute
    top 0
    left 0
    width 100%
    height 100%
    background rgba(0, 0, 0, .6)
    z-index 10
    flexbox()
    align-items flex-end
    .mask-content
      width 100%
      background #fff
      border-radius 15px 15px 0 0
      padding 25px 0 25px 15px
      box-sizing border-box
      .title
        font-weight bold
        font-size 16px
        letter-spacing 1PX
        border-left 4PX solid #ffc211
        padding-left 8px
      .tip
        color #888
        padding 10px 0 20px 12px
        border-bottom 1PX solid #efefef
      .item
        flexbox()
        align-items center
        padding 20px 0
        border-bottom 1PX solid #efefef
        .select-box
          flex-shrink 0
          .icon
            font-size 22px
            margin-right 10px
          .unselected
            color #bbb
        .img-box
          width 40px
          height 40px
          border-radius 50%
          overflow hidden
          margin-right 5px
          flex-shrink 0
          img
            width 100%
            height 100%
            object-fit cover
        .info-box
          padding-right 15px
          flex-grow 1
          .leader
            flexbox()
            align-items flex-end
            justify-content space-between
            margin-bottom 5px
            .name
              font-size 16px
            .tag
              .icon
                display inline-block
                width 0
                height 0
                border 7px solid transparent
                border-right-color $color-main
                vertical-align text-bottom
              .txt
                background $color-main
                color #fff
                font-size 10px
                padding-left 3px
                padding-right 8px
                border-radius 0 2px 2px 0
            .distance
              color #999
              .icon
                color $color-main
                font-size 12px
                margin-right 2px
          .address
            color #999
            line-height 1.2
      .btn-box
        padding-right 15px
        button
          background $color-main
          width 100%
          color #fff
          margin-top 25px
          line-height 2.5
          font-size 16px
          border-radius 20px
      .change-btn
        display inline-block
        color #999
        text-align center
        width 100%
        margin-top 10px
        letter-spacing 1PX
        .icon
          font-size 12px
</style>
